fun poll(): Int {
    val rows = mutableListOf<Row>()
    var applied = 0
    var last = 0L
    for (c in slot.peek()) when (val d = parse(c.data)) {
        is Begin -> rows.clear()
        is Row -> rows += d
        is Commit -> {
            if (c.lsn > index.appliedLsn) {          // not seen before
                rows.forEach(index::apply)
                index.markApplied(c.lsn)             // bookmark stored with the data
                applied++
            }
            last = c.lsn
            rows.clear()
        }
    }
    if (last > 0) slot.confirm(last)                 // after applying: a crash means a replay, not a loss
    return applied
}
// Confirm after applying. Confirming first would let PostgreSQL drop changes the index never got.
